mapper.select:
select 

from FIN_PRODUCT_VALUATION_PARA
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and BRANCH = #{branch,jdbcType=DECIMAL}

mapper.delete:
delete from FIN_PRODUCT_VALUATION_PARA
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and BRANCH = #{branch,jdbcType=DECIMAL}

mapper.update:
update FIN_PRODUCT_VALUATION_PARA
set INT_ACCRUAL_MODE = #{intAccrualMode,jdbcType=VARCHAR},
    UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP},
    TAX_SCHE_ID = #{taxScheId,jdbcType=VARCHAR},
